from confluent_kafka import Consumer, TopicPartition, OFFSET_INVALID
def group_offsets(bootstrap, group, topic, partitions):
    if not isinstance(partitions,list) or not partitions or any(type(p) is not int or p<0 for p in partitions) or len(set(partitions))!=len(partitions):
        raise ValueError('unique nonnegative partition integers required')
    c=Consumer({'bootstrap.servers':bootstrap,'group.id':group,'enable.auto.commit':False,'log_level':0})
    try:
        rows=c.committed([TopicPartition(topic,p) for p in partitions],timeout=5)
        return {str(r.partition):None if r.offset==OFFSET_INVALID else r.offset for r in rows}
    finally:c.close()

from confluent_kafka import Consumer,TopicPartition,OFFSET_INVALID
import time
def lag_report(bootstrap,group,topic,now_ms):
    if type(now_ms) is not int or now_ms<0:raise ValueError('now_ms')
    c=Consumer({'bootstrap.servers':bootstrap,'group.id':group,'enable.auto.commit':False,'enable.auto.offset.store':False,'log_level':0})
    try:
        md=c.list_topics(topic,timeout=5).topics[topic]
        if md.error:raise ValueError('unknown topic')
        out={}
        for part in sorted(md.partitions):
            tp=TopicPartition(topic,part);low,high=c.get_watermark_offsets(tp,timeout=5,cached=False)
            committed=c.committed([tp],timeout=5)[0].offset
            missing=committed==OFFSET_INVALID
            start=low if missing else committed
            age=None;first=None
            if start<high:
                c.assign([TopicPartition(topic,part,max(start,low))]);deadline=time.monotonic()+5
                while time.monotonic()<deadline:
                    m=c.poll(.1)
                    if m is None:continue
                    if m.error():raise RuntimeError(str(m.error()))
                    first=m.offset();stamp=m.timestamp()[1]
                    age=None if stamp<0 else max(0,now_ms-stamp)
                    break
                if first is None:raise RuntimeError('unread backlog')
            out[str(part)]={'committed':None if missing else committed,'low':low,'high':high,
                'offset_lag':max(0,high-start),'first_uncommitted_offset':first,'age_ms':age}
        return out
    finally:c.close()

