from confluent_kafka import Consumer,TopicPartition,ConsumerGroupTopicPartitions
from confluent_kafka.admin import AdminClient
import json,os
def reset_offsets(bootstrap,group,topic,expected,targets,approval,snapshot_path,dry_run=False):
    if type(dry_run) is not bool or not targets or set(targets)!=set(expected):raise ValueError('partition snapshot')
    if any(type(p) is not int or p<0 or type(v) is not int or v<0 for d in (expected,targets) for p,v in d.items()):raise ValueError('offset integers')
    if approval!={'group':group,'topic':topic,'action':'reset_offsets'}:raise ValueError('approval')
    a=AdminClient({'bootstrap.servers':bootstrap,'log_level':0})
    state=a.describe_consumer_groups([group])[group].result(5)
    if state.members or state.state.name not in ('EMPTY','DEAD'):raise ValueError('stop consumer group first')
    c=Consumer({'bootstrap.servers':bootstrap,'group.id':group,'enable.auto.commit':False,'log_level':0})
    try:
        before={r.partition:r.offset for r in c.committed([TopicPartition(topic,p) for p in targets],timeout=5)}
        if before!=expected:raise ValueError('stale snapshot')
        for p,v in targets.items():
            low,high=c.get_watermark_offsets(TopicPartition(topic,p),timeout=5,cached=False)
            if not low<=v<=high:raise ValueError('outside retained interval')
        result={'before':{str(k):v for k,v in before.items()},'after':{str(k):v for k,v in targets.items()}}
        if dry_run:return result
        try:f=open(snapshot_path,'x',encoding='utf8')
        except FileExistsError as e:raise ValueError('snapshot already exists') from e
        with f:
            json.dump({'group':group,'topic':topic,**result},f);f.flush();os.fsync(f.fileno())
        request=ConsumerGroupTopicPartitions(group,[TopicPartition(topic,p,v) for p,v in targets.items()])
        a.alter_consumer_group_offsets([request])[group].result(5)
        return result
    finally:c.close()

