from confluent_kafka import TopicPartition
def audit_delivery(consumer, topic, partitions, connection):
    if not partitions or len(set(partitions)) != len(partitions) or any(type(p) is not int or p < 0 for p in partitions):
        raise ValueError('unique non-negative partitions required')
    committed = consumer.committed([TopicPartition(topic,p) for p in partitions],timeout=5)
    rows=[]
    for p,position in zip(partitions,committed):
        low,high=consumer.get_watermark_offsets(TopicPartition(topic,p),timeout=5,cached=False)
        offset=position.offset
        found=connection.execute('SELECT completed_next_offset FROM business_watermarks WHERE topic=? AND partition=?',(topic,p)).fetchone()
        done=found[0] if found else None
        if done is not None and (type(done) is not int or not low <= done <= high):
            raise ValueError('downstream watermark outside retained range')
        if offset >= 0 and not low <= offset <= high:
            raise ValueError('Kafka commit outside retained range')
        rows.append({'partition':p,'committed':offset if offset>=0 else None,'high':high,
                     'offset_lag':high-offset if offset>=0 else None,
                     'business_next':done,'business_pending_offset_span':high-done if done is not None else None})
    return {'partitions':rows,'kafka_caught_up':all(r['committed']==r['high'] for r in rows),
            'business_complete':all(r['business_next']==r['high'] for r in rows)}

