import json
def apply_record(consumer, connection, message, failpoint=None):
    if failpoint not in (None,'before_commit','after_commit'):
        raise ValueError('unknown failpoint')
    event=json.loads(message.value())
    if not isinstance(event,dict) or set(event)!={'event_id','amount'} or not isinstance(event['event_id'],str) or not event['event_id'] or type(event['amount']) is not int:
        raise ValueError('invalid event')
    with connection:
        old=connection.execute('SELECT amount FROM processed WHERE event_id=?',(event['event_id'],)).fetchone()
        if old is not None and old[0]!=event['amount']:
            raise ValueError('same event id with different payload')
        inserted=old is None
        if inserted:
            connection.execute('INSERT INTO processed VALUES(?,?)',(event['event_id'],event['amount']))
            connection.execute("UPDATE totals SET value=value+? WHERE name='balance'",(event['amount'],))
        if failpoint=='before_commit':raise RuntimeError('before_commit')
    if failpoint=='after_commit':raise RuntimeError('after_commit')
    consumer.commit(message=message,asynchronous=False)
    return {'applied':inserted,'next_offset':message.offset()+1}

