def capacity(admin, topic, group):
    metadata=admin.list_topics(topic=topic,timeout=5)
    info=metadata.topics[topic]
    if info.error:raise RuntimeError(str(info.error))
    description=admin.describe_consumer_groups([group])[group].result(5)
    owners={}
    active=0
    for member in description.members:
        assigned=[p.partition for p in member.assignment.topic_partitions if p.topic==topic]
        if assigned:active+=1
        for partition in assigned:
            if partition in owners:raise RuntimeError('duplicate partition owner')
            owners[partition]=member.member_id
    return {'partition_count':len(info.partitions),'member_count':len(description.members),
            'assigned_members':active,'idle_members':len(description.members)-active,
            'assigned_partitions':sorted(owners),'parallelism_ceiling':len(info.partitions)}

