import time
def bounded_transaction(producer, topic, payload, work, budget_ms):
    if type(budget_ms) is not int or not 50<=budget_ms<=5000 or not callable(work):
        raise ValueError('budget must be integer 50..5000ms and work callable')
    errors=[]
    started=time.monotonic()
    producer.begin_transaction()
    try:
        producer.produce(topic,payload,on_delivery=lambda error,message:errors.append(error))
        if producer.flush(5)!=0 or not errors or any(errors):raise RuntimeError('delivery not acknowledged')
        work()
        remaining=budget_ms/1000-(time.monotonic()-started)
        if remaining<=0:
            producer.abort_transaction(5)
            return {'committed':False,'reason':'budget_exceeded'}
        producer.commit_transaction(remaining)
    except BaseException:
        producer.abort_transaction(5)
        raise
    return {'committed':True,'reason':'committed'}

