from confluent_kafka import Consumer,TopicPartition
import time,uuid
def audit_retention(bootstrap,topic,subject_key):
    if not isinstance(subject_key,bytes) or not subject_key:
        raise ValueError('nonempty bytes key required')
    c=Consumer({'bootstrap.servers':bootstrap,'group.id':'audit-'+uuid.uuid4().hex,
                'enable.auto.commit':False,'auto.offset.reset':'earliest','log_level':0})
    retained=[];tombstones=[]
    try:
        md=c.list_topics(topic,timeout=5).topics[topic]
        if md.error:raise RuntimeError(str(md.error))
        for part in sorted(md.partitions):
            tp=TopicPartition(topic,part)
            low,high=c.get_watermark_offsets(tp,timeout=5,cached=False)
            c.assign([TopicPartition(topic,part,low)])
            seen=low;deadline=time.monotonic()+8
            while seen<high:
                if time.monotonic()>deadline:raise RuntimeError('bounded snapshot replay timed out')
                m=c.poll(.1)
                if m is None:
                    # Kafka high watermarks include transaction control offsets.
                    # The client's position can advance over non-data batches.
                    position=c.position([TopicPartition(topic,part)])[0].offset
                    if position>=high:seen=high
                    continue
                if m.error():raise RuntimeError(str(m.error()))
                if m.offset()>=high:break
                seen=m.offset()+1
                if m.key()==subject_key:
                    (tombstones if m.value() is None else retained).append([part,m.offset()])
        return {'retained_offsets':retained,'tombstone_offsets':tombstones,
                'physical_erasure_proven':False,
                'unverified_holders':['replicas','backups','downstream','replay']}
    finally:c.close()

