from confluent_kafka import TopicPartition
def forward_once(c,p,m,output_topic,external_effect,abort=False):
    p.begin_transaction()
    try:
        external_effect(m)
        p.produce(output_topic,key=m.key(),value=m.value())
        p.send_offsets_to_transaction([TopicPartition(m.topic(),m.partition(),m.offset()+1)],
                                      c.consumer_group_metadata(),8)
        if abort:p.abort_transaction(8)
        else:p.commit_transaction(8)
        return {'kafka_committed':not abort,'external_atomic':False}
    except BaseException:
        p.abort_transaction(8)
        raise

