_PARENT_PID=os.getpid()
def _parent_guard():
 libc=ctypes.CDLL(None,use_errno=True)
 if libc.prctl(1,signal.SIGTERM,0,0,0)!=0:os._exit(126)
 if os.getppid()!=_PARENT_PID:os.kill(os.getpid(),signal.SIGTERM)


def free_port():
 with socket.socket() as endpoint:endpoint.bind(('127.0.0.1',0));return endpoint.getsockname()[1]

class Loki:
 def __init__(self,auth=False,structured=False,overrides=None):
  self.overrides=overrides or {}
  self.binary=os.environ.get('LOKI_BINARY','/usr/local/bin/loki');self.process=None;self.auth=auth;self.structured=structured
  if not pathlib.Path(self.binary).is_file():raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Loki3.5.5 executable missing')
