  if isinstance(value,dict):return {k:canonical(v) for k,v in sorted(value.items())}
  if isinstance(value,list):return sorted(value) if all(isinstance(x,str) for x in value) else [canonical(x) for x in value]
  return value
 assert json.dumps(canonical(facts),sort_keys=True,separators=(',',':'))==json.dumps(canonical(expected),sort_keys=True,separators=(',',':')),'project document facts conflict with the native scenario'
