from urllib.parse import quote
def _ok(reply):
    status,value=reply
    if status not in (200,201):raise AssertionError((status,value))
    return value
def migrate(es,source,target,alias):
    old=_ok(es.request('GET','/'+source+'/_mapping'))[source]['mappings']
    if old.get('_source',{}).get('enabled',True) is False:raise ValueError('_source unavailable')
    settings=_ok(es.request('GET','/'+source+'/_settings'))[source]['settings']['index']
    bound=_ok(es.request('GET','/_alias/'+alias))
    if set(bound)!={source}:raise ValueError('read alias must refer only to frozen source')
    status,_=es.request('GET','/'+target+'/_settings')
    if status!=404:raise ValueError('destination must be new')
    selected={k:settings[k] for k in ('number_of_shards','number_of_replicas','analysis') if k in settings}
    _ok(es.request('PUT','/'+target,{'settings':selected,'mappings':old}))
    result=_ok(es.request('POST','/_reindex?refresh=true',{'source':{'index':source},'dest':{'index':target,'op_type':'create'}}))
    if result.get('failures'):raise ValueError('reindex item failures')
    def records(name):
        hits=_ok(es.request('POST','/'+name+'/_search',{'size':100,'query':{'match_all':{}}}))['hits']
        if hits['total']['value']>100:raise ValueError('teaching dataset exceeds declared bound')
        return {h['_id']:h['_source'] for h in hits['hits']}
    before=records(source);after=records(target)
    if before!=after or result['created']!=len(before):raise ValueError('record reconciliation failed')
    _ok(es.request('POST','/_aliases',{'actions':[{'remove':{'index':source,'alias':alias}},{'add':{'index':target,'alias':alias}}]}))
    return {'copied':len(after),'source_preserved':True,'alias':alias,'target':target}

