    result=ok(es.request('POST','/'+index+'/_search',{'size':100,'query':{'match_all':{}}}))
    return {hit['_id']:hit['_source'] for hit in result['hits']['hits']}
def index(es,name,mappings=None,settings=None):
    return ok(es.request('PUT','/'+name,{'settings':{'number_of_shards':1,'number_of_replicas':0,**(settings or {})},'mappings':mappings or {}}))
task.migrate=traced(task.migrate)
with Elasticsearch() as es:
    source,target,alias=ident(),ident(),ident();analyzer='a'+uuid.uuid4().hex[:8]
    mapping={'properties':{'message':{'type':'text','analyzer':analyzer},'event_code':{'type':'keyword'},'latency_ms':{'type':'long'}}}
    analysis={'analyzer':{analyzer:{'type':'custom','tokenizer':'keyword','filter':['lowercase']}}}
    index(es,source,mapping,{'analysis':analysis})
    rows={'a':{'message':'HELLO Mixed','event_code':'A-1','latency_ms':3},'b':{'message':'SECOND Event','event_code':'B-2','latency_ms':None},'c':{'message':'HELLO Mixed','event_code':'A-1','latency_ms':0}}
    for id,body in rows.items():put(es,source,id,body)
    ok(es.request('POST','/_aliases',{'actions':[{'add':{'index':source,'alias':alias}}]}))
    ok(es.request('PUT','/'+source+'/_settings',{'index.blocks.write':True}))
    original_uuid=ok(es.request('GET','/'+source+'/_settings'))[source]['settings']['index']['uuid']
    result=task.migrate(es,source,target,alias)
    assert result=={'copied':3,'source_preserved':True,'alias':alias,'target':target},result
    assert docs(es,source)==rows and docs(es,target)==rows and docs(es,alias)==rows
    assert set(ok(es.request('GET','/_alias/'+alias)))=={target}
    source_mapping=ok(es.request('GET','/'+source+'/_mapping'))[source]['mappings']
    assert ok(es.request('GET','/'+target+'/_mapping'))[target]['mappings']==source_mapping
    target_settings=ok(es.request('GET','/'+target+'/_settings'))[target]['settings']['index']
    assert target_settings['number_of_shards']=='1' and target_settings['number_of_replicas']=='0'
    assert target_settings['analysis']==analysis,'reindex did not carry the declared custom analyzer'
    for name in [source,target]:
        tokens=ok(es.request('POST','/'+name+'/_analyze',{'analyzer':analyzer,'text':'HELLO Mixed'}))
        assert [t['token'] for t in tokens['tokens']]==['hello mixed']
    assert ok(es.request('GET','/'+source+'/_settings'))[source]['settings']['index']['uuid']==original_uuid
    put(es,alias,'new',{'message':'AFTER Cutover','event_code':'C','latency_ms':8})
