    try:task.migrate(es,source,target,alias)
    except ValueError:pass
    else:raise AssertionError('existing target or stale alias must not be overwritten')
    # Actual rollback retains all original frozen records; no source reconstruction is required.
    ok(es.request('POST','/_aliases',{'actions':[{'remove':{'index':target,'alias':alias}},{'add':{'index':source,'alias':alias}}]}))
