    put(es,opaque,'1',{'message':'source intentionally unavailable'})
    ok(es.request('POST','/_aliases',{'actions':[{'add':{'index':opaque,'alias':opaque_alias}}]}))
    try:task.migrate(es,opaque,opaque_target,opaque_alias)
    except ValueError:pass
    else:raise AssertionError('unavailable _source was not rejected')
    assert es.request('GET','/'+opaque_target+'/_settings')[0]==404
    assert set(ok(es.request('GET','/_alias/'+opaque_alias)))=={opaque}

