import json,time
from urllib.parse import quote
def _ok(reply):
    status,value=reply
    if status not in (200,201):raise AssertionError((status,value))
    return value
def publish_revision(es,raw,audit,current,event_id,version,content):
    if not isinstance(event_id,str) or not event_id or type(version) is not int or version<2 or not isinstance(content,dict):raise ValueError('invalid correction')
    eid=quote(event_id,safe='')
    original=_ok(es.request('GET','/'+raw+'/_doc/'+eid))['_source']
    previous=_ok(es.request('GET','/'+current+'/_doc/'+eid))['_source']
    if previous['revision']>version:raise ValueError('stale revision')
    if previous['revision']==version:
        if previous['content']!=content:raise ValueError('same revision differs')
        return {'revision':version,'replayed':True}
    record={'event_id':event_id,'revision':version,'content':content,'raw_id':event_id,'event_time':original['event_time']}
    aid=quote(event_id+':'+str(version),safe='')
    status,value=es.request('PUT','/'+audit+'/_doc/'+aid+'?op_type=create&refresh=wait_for',record)
    if status==409:
        if _ok(es.request('GET','/'+audit+'/_doc/'+aid))['_source']!=record:raise ValueError('immutable correction differs')
    else:_ok((status,value))
    _ok(es.request('PUT','/'+current+'/_doc/'+eid+'?version_type=external&version='+str(version)+'&refresh=wait_for',record))
    return {'revision':version,'replayed':False}

