        'ecs':{'properties':{'version':{'type':'keyword'}}},'event':{'properties':{'duration':{'type':'long'}}},
        'client':{'properties':{'ip':{'type':'ip'}}},'user':{'properties':{'id':{'type':'keyword'}}},
        '@timestamp':{'type':'date'},'raw':{'type':'object','enabled':False}}}
    settings={'number_of_shards':1,'number_of_replicas':0}
    _ok(es.request('PUT','/'+index,{'settings':settings,'mappings':mappings}))
    _ok(es.request('PUT','/'+quarantine,{'settings':settings,'mappings':{'dynamic':False,'properties':{'raw':{'type':'object','enabled':False},'error':{'properties':{'message':{'type':'keyword','ignore_above':1024}}}}}}))
    snapshot="""def original=new HashMap(); for (def entry:ctx.entrySet()) {if (!entry.getKey().startsWith('_')) original.put(entry.getKey(),entry.getValue());} ctx.raw=original;"""
    normalize="""def raw=ctx.raw; def kind=raw.source_kind;
    if (kind!='a' && kind!='b') throw new IllegalArgumentException('unknown source namespace');
    double seconds=0.0; boolean hasDuration=raw.duration!=null;
    if (hasDuration) {
      if (kind=='a') {if (!(raw.duration instanceof Number)) throw new IllegalArgumentException('milliseconds must be numeric'); seconds=((Number)raw.duration).doubleValue()/1000.0;}
      else {if (!(raw.duration instanceof String)) throw new IllegalArgumentException('seconds must be a string'); seconds=Double.parseDouble(raw.duration);}
      if (!(seconds>=0) || seconds>1000000) throw new IllegalArgumentException('duration outside supported finite range');
    }
    if (raw.user_id!=null && (!(raw.user_id instanceof String) || raw.user_id.length()==0)) throw new IllegalArgumentException('invalid user namespace identifier');
    for (def key:new ArrayList(ctx.keySet())) {if (!key.startsWith('_') && key!='raw') ctx.remove(key);}
    ctx.source_kind=kind;ctx.ecs=['version':'8.17.0'];ctx.event=new HashMap();
    if (hasDuration) ctx.event.duration=Math.round(seconds*1000000000.0);
    if (raw.user_id!=null) ctx.user=['id':kind+':'+raw.user_id];
    if (raw.ip!=null) ctx.client=['ip':raw.ip];
    if (raw.timestamp!=null) ctx['@timestamp']=raw.timestamp;"""
    processors=[{'script':{'source':snapshot}},{'script':{'source':normalize}},
        {'convert':{'field':'client.ip','type':'ip','ignore_missing':True}},
        {'date':{'field':'@timestamp','formats':['ISO8601','UNIX_MS'],'if':"ctx.containsKey('@timestamp') && ctx['@timestamp'] != null"}}]
    failures=[{'set':{'field':'error.message','value':'{{ _ingest.on_failure_message }}'}},{'set':{'field':'_index','value':quarantine}}]
    _ok(es.request('PUT','/_ingest/pipeline/'+pipeline,{'processors':processors,'on_failure':failures}))
    return {'index':index,'quarantine':quarantine,'pipeline':pipeline,'ecs_version':'8.17.0'}

def compatibility_total(es,indices):
    script="""if (doc.containsKey('event.duration') && doc['event.duration'].size()>0) emit(((Number)doc['event.duration'].value).doubleValue());
    else if (doc.containsKey('duration_ms') && doc['duration_ms'].size()>0) emit(((Number)doc['duration_ms'].value).doubleValue()*1000000.0);"""
    reply=_ok(es.request('POST','/'+indices+'/_search',{'size':0,'runtime_mappings':{'duration_ns':{'type':'double','script':{'source':script}}},'aggs':{'total':{'sum':{'field':'duration_ns'}}}}))
    return reply['aggregations']['total']['value']

