import json,time
from urllib.parse import quote
def _ok(reply):
    status,value=reply
    if status not in (200,201):raise AssertionError((status,value))
    return value
import hashlib
def upsert_child(es,parents,children,parent_id,child_id,version,fields):
    if not isinstance(parent_id,str) or not parent_id or not isinstance(child_id,str) or not child_id or type(version) is not int or version<1:raise ValueError('invalid child identity/version')
    if fields is not None and (not isinstance(fields,dict) or set(fields)!={'kind','color'} or any(not isinstance(v,str) for v in fields.values())):raise ValueError('invalid child fields')
    status,value=es.request('GET','/'+parents+'/_doc/'+quote(parent_id,safe=''))
    if status==404:raise ValueError('orphan child is forbidden')
    _ok((status,value))
    record={'parent_id':parent_id,'child_id':child_id,'revision':version,'deleted':fields is None}
    if fields is not None:record.update(fields)
    id=quote(hashlib.sha256(json.dumps([parent_id,child_id],ensure_ascii=False,separators=(',',':')).encode()).hexdigest(),safe='');routing=quote(parent_id,safe='')
    status,value=es.request('PUT','/'+children+'/_doc/'+id+'?routing='+routing+'&version_type=external&version='+str(version)+'&refresh=wait_for',record)
    if status==409:
        previous=_ok(es.request('GET','/'+children+'/_doc/'+id+'?routing='+routing))['_source']
        if previous==record:return {'updated':False,'revision':version}
        raise ValueError('stale or conflicting child revision')
    _ok((status,value));return {'updated':True,'revision':version}

def migrate_nested(es,parents,children):
    status,_=es.request('GET','/'+children+'/_mapping')
    if status==404:
        mapping={'_routing':{'required':True},'dynamic':'strict','properties':{'parent_id':{'type':'keyword'},'child_id':{'type':'keyword'},'revision':{'type':'long'},'deleted':{'type':'boolean'},'kind':{'type':'keyword'},'color':{'type':'keyword'}}}
        _ok(es.request('PUT','/'+children,{'settings':{'number_of_shards':1,'number_of_replicas':0},'mappings':mapping}))
    elif status!=200:raise ValueError('destination unavailable')
    hits=_ok(es.request('POST','/'+parents+'/_search',{'size':100,'query':{'match_all':{}}}))['hits']
    if hits['total']['value']>100:raise ValueError('training parent bound exceeded')
    count=0
    for hit in hits['hits']:
        row=hit['_source']
        for child in row['children']:
            result=upsert_child(es,parents,children,hit['_id'],child['id'],row['revision'],{'kind':child['kind'],'color':child['color']})
            count+=int(result['updated'])
    return {'new_child_writes':count,'parent_documents':len(hits['hits']),'atomic_parent_child_snapshot':False}

def matching_parents(es,parents,children,kind,color):
    query={'bool':{'filter':[{'term':{'kind':kind}},{'term':{'color':color}},{'term':{'deleted':False}}]}}
    result=_ok(es.request('POST','/'+children+'/_search',{'size':0,'query':query,'aggs':{'parents':{'terms':{'field':'parent_id','size':100}}}}))
    found=[]
    for bucket in result['aggregations']['parents']['buckets']:
        status,value=es.request('GET','/'+parents+'/_doc/'+quote(bucket['key'],safe=''))
        if status==200:found.append(bucket['key'])
        elif status!=404:_ok((status,value))
    return sorted(found)

def delete_parent(es,parents,children,parent_id):
    result=_ok(es.request('POST','/'+children+'/_delete_by_query?refresh=true',{'query':{'term':{'parent_id':parent_id}}}))
    if result.get('failures') or result.get('version_conflicts') or result.get('timed_out'):raise ValueError('child cleanup incomplete')
    status,value=es.request('DELETE','/'+parents+'/_doc/'+quote(parent_id,safe='')+'?refresh=wait_for')
    if status not in (200,404):_ok((status,value))
    return {'deleted_children':result['deleted'],'parent_removed':True}

