    child_before=ok(es.request('GET','/'+children+'/_doc/'+initial_id+'?routing=p1'))
    assert child_before['_routing']=='p1'
    before_stats=ok(es.request('GET','/'+children+'/_stats/indexing,docs,store'))
    assert task.upsert_child(es,parents,children,'p1','c1',2,{'kind':'A','color':'blue'})=={'updated':True,'revision':2}
    assert ok(es.request('GET','/'+parents+'/_doc/p1'))==parent_before,'single child update rewrote the parent document'
    assert task.matching_parents(es,parents,children,'A','blue')==['p1','p2','p3']
    stable=docs(es,children)
    assert task.upsert_child(es,parents,children,'p1','c1',2,{'kind':'A','color':'blue'})=={'updated':False,'revision':2}
    for version,body in [(1,{'kind':'A','color':'red'}),(2,{'kind':'A','color':'different'}),(True,{'kind':'A','color':'blue'})]:
        try:task.upsert_child(es,parents,children,'p1','c1',version,body)
