    assert task.upsert_child(es,parents,children,'p1','c1',3,None)=={'updated':True,'revision':3}
    assert task.matching_parents(es,parents,children,'A','blue')==['p2','p3']
    try:task.upsert_child(es,parents,children,'p1','c1',2,{'kind':'A','color':'blue'})
    except ValueError:pass
