    assert task.upsert_child(es,parents,children,'p2','new',1,{'kind':'A','color':'blue'})=={'updated':True,'revision':1}
    assert task.matching_parents(es,parents,children,'A','blue')==['p2','p3'],'parent-level counts were replaced by child document counts'
    # Actual native old-model rewrite compared with a single independent child write.
    rewritten=copy.deepcopy(rows['p1']);rewritten['children'][0]['color']='blue'
    comparison_before=ok(es.request('GET','/'+comparison+'/_doc/p1'))
    put(es,comparison,'p1',rewritten)
    assert ok(es.request('GET','/'+comparison+'/_doc/p1'))['_seq_no']>comparison_before['_seq_no']
