    deleted=task.delete_parent(es,parents,children,'p2');assert deleted=={'deleted_children':2,'parent_removed':True}
    assert task.matching_parents(es,parents,children,'A','blue')==['p3']
    assert all(row['parent_id']!='p2' for row in docs(es,children).values())
    before=docs(es,children)
    try:task.upsert_child(es,parents,children,'p2','orphan',1,{'kind':'A','color':'blue'})
    except ValueError:pass
    else:raise AssertionError('orphan write accepted')
    assert docs(es,children)==before
    # A bypassed pre-existing orphan must not leak into parent results and is cleanable.
    ok(es.request('PUT','/'+children+'/_doc/gone:orphan?routing=gone&refresh=wait_for',{'parent_id':'gone','child_id':'orphan','revision':1,'deleted':False,'kind':'A','color':'blue'}))
    assert task.matching_parents(es,parents,children,'A','blue')==['p3']
    assert task.delete_parent(es,parents,children,'gone')=={'deleted_children':1,'parent_removed':True}
    assert all(row['parent_id'] not in ('gone','p2') for row in docs(es,children).values())
    # Both components may contain a colon; concatenation would collide in one shard.
    for parent in ['a:b','a']:put(es,parents,parent,{'revision':1,'children':[]})
    try:
        assert task.upsert_child(es,parents,children,'a:b','c',1,{'kind':'X','color':'one'})=={'updated':True,'revision':1}
        assert task.upsert_child(es,parents,children,'a','b:c',1,{'kind':'X','color':'two'})=={'updated':True,'revision':1}
    except Exception as error:raise AssertionError('legal parent/child IDs collided') from error
    collision_rows={id:row for id,row in docs(es,children).items() if row['parent_id'] in ('a:b','a')}
    assert len(collision_rows)==2 and {(row['parent_id'],row['child_id']) for row in collision_rows.values()}=={('a:b','c'),('a','b:c')}
    assert task.delete_parent(es,parents,children,'a:b')=={'deleted_children':1,'parent_removed':True}
    assert task.delete_parent(es,parents,children,'a')=={'deleted_children':1,'parent_removed':True}
    assert docs(es,parents)=={'p1':rows['p1'],'p3':rows['p3']}

