from confluent_kafka import Producer
from confluent_kafka.admin import AclBinding,AclOperation,AclPermissionType,ResourceType,ResourcePatternType
def probe(config,topic):
    codes=[];opts=dict(config,log_level=0)
    opts['message.timeout.ms']=1800
    opts['error_cb']=lambda e:codes.append(e.code())
    p=Producer(opts);p.produce(topic,b'probe',on_delivery=lambda e,m:codes.append(e.code() if e else 0))
    p.flush(3)
    layer=('authentication' if any(c in (-169,58) for c in codes) else
           'authorization' if 29 in codes else 'ok' if 0 in codes else 'transport')
    return {'layer':layer,'codes':sorted(set(codes))}
def grant_write(admin,principal,topic):
    if not isinstance(principal,str) or not principal.startswith('User:') or not principal[5:] or '*' in principal or not isinstance(topic,str) or not topic or topic=='*':raise ValueError('exact principal and topic required')
    bindings=[AclBinding(ResourceType.TOPIC,topic,ResourcePatternType.LITERAL,principal,'*',op,AclPermissionType.ALLOW)
              for op in (AclOperation.WRITE,AclOperation.DESCRIBE)]
    for future in admin.create_acls(bindings).values():future.result(5)

