import base64,json
def process_one(c,p,m,decode,max_attempts,dlq):
    if type(max_attempts) is not int or not 1<=max_attempts<=10:raise ValueError('bounded retries 1..10')
    error=None
    for attempt in range(max_attempts):
        try:result=decode(m.value());break
        except (ValueError,UnicodeError) as exc:error=type(exc).__name__
    else:
        envelope={'topic':m.topic(),'partition':m.partition(),'offset':m.offset(),
                  'payload_b64':base64.b64encode(m.value()).decode(),'error':error}
        outcomes=[]
        p.produce(dlq,key=f'{m.topic()}:{m.partition()}:{m.offset()}'.encode(),value=json.dumps(envelope).encode(),
                  on_delivery=lambda e,msg:outcomes.append(e))
        if p.flush(5) or len(outcomes)!=1 or outcomes[0] is not None:raise RuntimeError('DLQ not acknowledged')
        c.commit(message=m,asynchronous=False)
        return {'status':'quarantined','attempts':max_attempts}
    c.commit(message=m,asynchronous=False)
    return {'status':'processed','attempts':attempt+1}

