def create_order(db,order_id,amount):
    if type(amount) is not int or amount<=0:raise ValueError('positive amount')
    if db.in_transaction:raise ValueError('idle DB connection required')
    db.execute('BEGIN')
    try:
        db.execute('insert into orders values(?,?)',(order_id,amount))
        db.execute('insert into outbox(id,payload,sent) values(?,?,0)',(order_id,json.dumps({'id':order_id,'amount':amount})))
        db.commit()
    except BaseException:db.rollback();raise
def publish_pending(db,p,topic,after_ack=None):
    if db.in_transaction:raise ValueError('idle DB connection required')
    sent=0
    for event_id,payload in db.execute('select id,payload from outbox where sent=0 order by seq').fetchall():
        errors=[]
        p.produce(topic,key=event_id.encode(),value=payload.encode(),on_delivery=lambda e,m:errors.append(e))
        if p.flush(5) or len(errors)!=1 or errors[0] is not None:raise RuntimeError('Kafka ACK missing; keep outbox')
        if after_ack:after_ack(event_id)
        with db:db.execute('update outbox set sent=1 where id=?',(event_id,))
        sent+=1
    return sent
def apply_event(db,m):
    event=json.loads(m.value())
    if db.in_transaction:raise ValueError('idle DB connection required')
    db.execute('BEGIN')
    try:
        inserted=db.execute('insert or ignore into applied values(?)',(event['id'],)).rowcount
        if inserted:db.execute('insert into effects values(?,?)',(event['id'],event['amount']))
        db.commit()
    except BaseException:db.rollback();raise
    return bool(inserted)

