import time,uuid
def roundtrip(bootstrap,topic,partition,key,value):
    if type(partition) is not int or partition<0:raise ValueError('partition')
    a=AdminClient({'bootstrap.servers':bootstrap,'log_level':0})
    md=a.list_topics(topic,timeout=5).topics[topic].partitions[partition]
    c=Consumer({'bootstrap.servers':bootstrap,'group.id':'route-'+uuid.uuid4().hex,'enable.auto.commit':False,'log_level':0})
    try:
        low,start=c.get_watermark_offsets(TopicPartition(topic,partition),timeout=5,cached=False)
        p=Producer({'bootstrap.servers':bootstrap,'acks':'all','compression.type':'none','log_level':0})
        result=[]
        p.produce(topic,partition=partition,key=key,value=value,on_delivery=lambda e,m:result.append((e,m.offset())))
        if p.flush(8) or len(result)!=1 or result[0][0] is not None:raise RuntimeError('native produce ACK required')
        c.assign([TopicPartition(topic,partition,start)]);deadline=time.monotonic()+5
        while time.monotonic()<deadline:
            m=c.poll(.1)
            if m is None:continue
            if m.error():raise RuntimeError(str(m.error()))
            return {'leader':md.leader,'replicas':list(md.replicas),'isr':list(md.isrs),
                    'offset':m.offset(),'key':m.key(),'value':m.value()}
        raise RuntimeError('native consume timeout')
    finally:c.close()

