from pathlib import Path
import json,subprocess,time
def preferred(admin,topic,partition):
    before=admin.list_topics(topic,timeout=5).topics[topic].partitions[partition]
    result=admin.elect_leaders(ElectionType.PREFERRED,[TopicPartition(topic,partition)]).result(8)
    for error in result.values():
        if error is not None and error.code()!=84:raise RuntimeError(str(error))
    deadline=time.monotonic()+10
    while time.monotonic()<deadline:
        after=admin.list_topics(topic,timeout=3).topics[topic].partitions[partition]
        if after.leader==before.replicas[0]:return after.leader
        time.sleep(.1)
    raise RuntimeError('preferred leader did not converge')
def reassign(admin,command,topic,partition,replicas,path):
    if not isinstance(replicas,list) or not replicas or any(type(n) is not int or n<=0 for n in replicas) or len(set(replicas))!=len(replicas):raise ValueError('unique broker ids')
    plan={'version':1,'partitions':[{'topic':topic,'partition':partition,'replicas':replicas}]}
    Path(path).write_text(json.dumps(plan))
    result=subprocess.run(command+['--reassignment-json-file',str(path),'--execute'],text=True,capture_output=True,timeout=12)
    if result.returncode:raise RuntimeError(result.stdout+result.stderr)
    deadline=time.monotonic()+15
    while time.monotonic()<deadline:
        md=admin.list_topics(topic,timeout=3).topics[topic].partitions[partition]
        if list(md.replicas)==replicas and set(md.isrs)==set(replicas):return list(md.replicas)
        time.sleep(.1)
    raise RuntimeError('native reassignment incomplete')

