def health(admin,topic,quorum_command):
    metadata=admin.list_topics(topic,timeout=4).topics[topic]
    under=sorted(p for p,md in metadata.partitions.items() if len(md.isrs)<len(md.replicas))
    offline=sorted(p for p,md in metadata.partitions.items() if md.leader<0)
    available=False;leader=None;watermark=None;lag=None;voters=[]
    try:
        result=subprocess.run(quorum_command,text=True,capture_output=True,timeout=6)
        if result.returncode==0:
            def integer(label):
                match=re.search(r'^'+label+r':\s+(-?\d+)',result.stdout,re.M)
                return int(match.group(1)) if match else None
            leader=integer('LeaderId');watermark=integer('HighWatermark');lag=integer('MaxFollowerLag')
            match=re.search(r'^CurrentVoters:\s+(.+)$',result.stdout,re.M)
            voters=sorted(x['id'] for x in json.loads(match.group(1))) if match else []
            available=leader is not None and leader>=0 and len(voters)>=3
    except subprocess.TimeoutExpired:pass
    return {'quorum_available':available,'controller_leader':leader,'metadata_high_watermark':watermark,
            'metadata_max_follower_lag':lag,'voters':voters,'under_replicated':under,'offline':offline}

