from pathlib import Path
import json,subprocess,time
def evacuate(admin,command,retiring,plan,path):
    md=admin.list_topics(timeout=5)
    if type(retiring) is not int or retiring<=0 or not isinstance(plan,list) or not plan:raise ValueError('positive broker id and nonempty plan required')
    for row in plan:
        if not isinstance(row,dict) or not {'topic','partition','replicas'}<=set(row) or not isinstance(row['topic'],str) or row['topic'] not in md.topics or type(row['partition']) is not int or row['partition'] not in md.topics[row['topic']].partitions or not isinstance(row['replicas'],list):raise ValueError('known topic/partition and explicit replica list required')
    actual={(name,p) for name,topic in md.topics.items() for p,part in topic.partitions.items() if retiring in part.replicas}
    proposed={(row['topic'],row['partition']) for row in plan}
    if len(proposed)!=len(plan):raise ValueError('duplicate partition plan')
    for row in plan:
        replicas=row['replicas'];part=md.topics[row['topic']].partitions[row['partition']]
        if not replicas or any(type(n) is not int or n not in md.brokers for n in replicas) or len(replicas)!=len(part.replicas) or retiring in replicas or len(set(replicas))!=len(replicas):raise ValueError('preserve replica count and use live nonretiring brokers')
    if actual and proposed!=actual:raise ValueError('all retiring replicas must be planned')
    if not actual:
        if any(list(md.topics[r['topic']].partitions[r['partition']].replicas)!=r['replicas'] for r in plan):raise ValueError('existing assignment does not match plan')
        if any(set(md.topics[r['topic']].partitions[r['partition']].isrs)!=set(r['replicas']) for r in plan):raise ValueError('target ISR is not healthy')
        return True
    Path(path).write_text(json.dumps({'version':1,'partitions':plan}))
    result=subprocess.run(command+['--reassignment-json-file',str(path),'--execute'],text=True,capture_output=True,timeout=12)
    if result.returncode:raise RuntimeError(result.stdout+result.stderr)
    deadline=time.monotonic()+15
    while time.monotonic()<deadline:
        current=admin.list_topics(timeout=3)
        remaining=any(retiring in part.replicas for topic in current.topics.values() for part in topic.partitions.values())
        healthy=all(set(current.topics[r['topic']].partitions[r['partition']].isrs)==set(r['replicas']) and list(current.topics[r['topic']].partitions[r['partition']].replicas)==r['replicas'] for r in plan)
        if not remaining and healthy:return True
        time.sleep(.1)
    raise RuntimeError('retiring replica or incomplete ISR remains')

