# UNVERIFIED native case support; no scenario runs on import.
import json,pathlib,time,threading

from native_c import Roles,require_observable,wait_for,metric_observations

class NativeMinimumPending(RuntimeError):pass

def gateway_rpc_count(cluster):
 # Exact pinned-source metric: indexgateway/metrics.go plus gateway.go GetChunkRef.
 rows=require_observable(cluster.metrics('index-gateway'),'loki_index_gateway_prefilter_chunks_count')
 return sum(value for name,value in rows.items() if 'route="chunk_refs"' in name)

def eventual_query(cluster,query,start,end,seconds=70):
 def query_once():
  try:return cluster.query(query,start,end) or None
  except RuntimeError as error:
   if str(error).startswith('NATIVE_QUERY_ERROR:'):return None
   raise
 return wait_for(query_once,'actual persisted query and index upload',seconds)

def event_ids(rows):return sorted(json.loads(value[1])['event_id'] for row in rows for value in row['values'])

def run_gateway_case(task):
 """Full staged074 path; not executed/verified and disabled by draft checker."""
 with Roles(log_level='debug') as cluster:
  now=time.time_ns();old=now-2*86400*10**9
  # The histogram is lazily instantiated. It must really appear after GetChunkRef;
  # absent-before is not exported zero and is recorded separately.
  raw_before=cluster.metrics('index-gateway')
  cluster.push([[str(old+i),json.dumps({'event_id':i,'message':'stored-old'})] for i in range(4)],app='gateway-old')
  for name in cluster.names:
   if name.startswith('ingester-'):
    status,body=cluster.request(name,'/flush',method='POST',raw=True)
    if status not in (200,204):raise NativeMinimumPending('actual flush endpoint/target not supported: '+str(status)+body[:160])
  # Native graceful shutdown builds the actual TSDB heads and uploads them;
  # flush alone does not guarantee publication before the next upload tick.
  # Restart the same owned ingesters before the read/write outage experiment.
  for name in cluster.names:
   if name.startswith('ingester-'):cluster.stop_role(name)
  for name in cluster.names:
   if name.startswith('ingester-'):cluster.start_role(name)
  def distributor_sees_active_ingesters():
   import re
   status,body=cluster.request('distributor','/ring',raw=True)
   if status!=200:return None
   rows=re.findall(r'<tr[^>]*>(.*?)</tr>',body,re.S)
   active={name:next((row for row in rows if name in row and re.search(r'>\s*ACTIVE\s*<',row)),None) for name in cluster.names if name.startswith('ingester-')}
   return active if all(active.values()) else None
  active_ingester_rows=wait_for(distributor_sees_active_ingesters,'distributor actual ACTIVE ring after graceful publication restart',seconds=15)
  before_rows=eventual_query(cluster,'{app="gateway-old"}',old-10,old+100)
  before_ok=event_ids(before_rows)==[0,1,2,3];assert before_ok
  rpc_after_first=gateway_rpc_count(cluster);assert rpc_after_first>0,'native index gateway GetChunkRef observations required'
  fault_started=time.monotonic();cluster.stop_role('index-gateway',crash=True)
  cluster.restart_role('querier',clear_cache=True)
  wait_for(lambda:sum(require_observable(cluster.metrics('query-scheduler'),'query_scheduler_connected_querier_clients').values())>0,'real querier reconnected after cold-cache restart')
  write_status=cluster.push([[str(now),json.dumps({'event_id':4,'message':'written-during-gateway-outage'})]],app='gateway-new')
  during_failed=False;actual_error=None;query_log=cluster.root/'querier/native.log';before_fault_query_log_bytes=query_log.stat().st_size
  try:cluster.query('{app="gateway-old"}',old-10,old+100)
  except RuntimeError as error:
   if not str(error).startswith('NATIVE_QUERY_ERROR:'):raise
   during_failed=True;actual_error=str(error)
  assert during_failed,'a warm cache cannot count as the required cold-gateway failure'
  querier_fault_log=query_log.read_bytes()[before_fault_query_log_bytes:].decode(errors='replace')
  dependency_endpoint='127.0.0.1:'+str(cluster.grpc['index-gateway']);diagnostic=actual_error+'\n'+querier_fault_log
  failed_client_lines=[line for line in querier_fault_log.splitlines() if dependency_endpoint in line and 'client do failed for instance' in line and 'connection refused' in line.lower()]
  executing_lines=[line for line in querier_fault_log.splitlines() if 'component=querier' in line and 'executing query' in line and 'gateway-old' in line]
  if not (failed_client_lines and executing_lines):
   raise NativeMinimumPending('074 query failed but specific native index-gateway endpoint/refusal not attributable; preserve actual error/log, do not treat generic scheduler/ring/timeout failure as gateway proof')

  cluster.start_role('index-gateway');restored_at=time.monotonic()
  after_rows=eventual_query(cluster,'{app="gateway-old"}',old-10,old+100,seconds=15)
  new_rows=eventual_query(cluster,'{app="gateway-new"}',now-10,now+100,seconds=15)
  rpc_after_restore=gateway_rpc_count(cluster);assert rpc_after_restore>0,'restored native gateway must receive actual query RPCs'
  facts={'old_before_ok':before_ok,'write_during_ok':write_status==204,'gateway_rpc_observed':rpc_after_first>0,'old_during_failed':during_failed,'old_after_ok':event_ids(after_rows)==[0,1,2,3],'new_after_ok':event_ids(new_rows)==[4]}
  assert all(facts.values());assert task.gateway_result(facts)=={'split_path_proven':True,'write_health_proves_read_health':False}
  for missing in facts:
   incomplete={**facts,missing:False};assert task.gateway_result(incomplete)=={'split_path_proven':False,'write_health_proves_read_health':False}
  for invalid in [None,0,'true']:
   try:task.gateway_result({**facts,'write_during_ok':invalid})
   except ValueError:pass
   else:raise AssertionError('observation type must not be coerced')
  print('NATIVE_C_GATEWAY_FACTS:'+json.dumps({'facts':facts,'actual_query_error':actual_error,'specific_failed_gateway_endpoint':dependency_endpoint,'querier_fault_log':querier_fault_log,'actual_gateway_client_failures':failed_client_lines,'actual_querier_request_executions':executing_lines,'restored_get_chunk_ref_count':rpc_after_restore,'fault_started':fault_started,'real_active_ingester_rows':active_ingester_rows,'restored_at':restored_at,'get_chunk_ref_histogram_count':rpc_after_first,'before_metric_exported':'loki_index_gateway_prefilter_chunks_count' in raw_before}),flush=True)

