def metric_observations(text):
 """Only native exported observations. No absent series is manufactured as zero."""
 result={}
 for line in text.splitlines():
  if not line or line.startswith('#'):continue
  name,_,value=line.rpartition(' ')
  try:result[name]=float(value)
  except ValueError:continue
 return result

def require_observable(text,fragment):
 rows={name:value for name,value in metric_observations(text).items() if fragment in name}
 if not rows:raise RuntimeError('NATIVE_CAPABILITY_UNVERIFIED: actual metric absent: '+fragment)
 return rows

