import json,pathlib,time,threading

from native_c import Roles,require_observable,wait_for,metric_observations

class NativeMinimumPending(RuntimeError):pass

def event_ids(rows):return sorted(json.loads(value[1])['event_id'] for row in rows for value in row['values'])

def observed_statistics(response):
 # Pinned stats.proto: summary times are seconds; store download time is ns.
 try:
  stats=response['data']['stats'];summary=stats['summary'];store=stats['querier']['store']
  measured={'wait':float(summary['queueTime']),'wall':float(summary['execTime']),'download':int(store['chunksDownloadTime'])/10**9,'scan':int(summary['totalBytesProcessed'])}
 except (KeyError,TypeError,ValueError) as error:raise NativeMinimumPending('actual query statistics missing; no default zeros permitted: '+repr(error))
 assert all(value>=0 for value in measured.values());return measured,stats

def independent_executor_observation(cluster):
 # Pinned pkg/logql/metrics.go: histogram records engine's own Summary.ExecTime.
 # This is read from the actual querier PID, not frontend wall minus queue.
 exported=metric_observations(cluster.metrics('querier'))
 sums={key:value for key,value in exported.items() if key.split('{',1)[0]=='loki_logql_querystats_latency_seconds_sum' and 'status_code="200"' in key and 'type="limited"' in key and 'range="range"' in key}
 counts={key:value for key,value in exported.items() if key.split('{',1)[0]=='loki_logql_querystats_latency_seconds_count' and 'status_code="200"' in key and 'type="limited"' in key and 'range="range"' in key}
 if not sums or not counts:raise NativeMinimumPending('067 actual querier engine histogram is absent; frontend wall is not exclusive execution')
 return {'seconds_sum':sum(sums.values()),'query_count':sum(counts.values()),'native_sum_series':sums,'native_count_series':counts,'querier_pid':cluster.processes['querier'].process.pid}

def run_queue_scan_case(task):
 """Staged actual scheduler queue and actual parser scan; unexecuted."""
 with Roles(log_level='info',parallelise_shardable_queries=False) as cluster:
  n=time.time_ns();payload=[[str(n+i),json.dumps({'id':i,'text':'scan-'+str(i)+'x'*1024})] for i in range(4096)]
  cluster.push(payload,app='analysis');cluster.stop_role('querier')
  output={}
