  try:
   queue_rows=wait_for(lambda:({name:value for name,value in metric_observations(cluster.metrics('query-scheduler')).items() if 'query_scheduler_queue_length' in name and 'user="a"' in name and value>0}) or None,'real query entered scheduler queue',seconds=4)
   queue_seen=time.monotonic();time.sleep(.35);cluster.start_role('querier');pending.join(timeout=30)
   if pending.is_alive() or 'error' in output:raise NativeMinimumPending('actual queued request did not finish: '+str(output.get('error')))
  finally:
   if cluster.processes['querier'].process.poll() is not None:cluster.start_role('querier')
   pending.join(timeout=31)
   if pending.is_alive():raise NativeMinimumPending('own real request thread did not drain')
  queued_ids=sorted(json.loads(value[1])['id'] for row in output['response']['data']['result'] for value in row['values'])
  assert queued_ids==list(range(4096)),'queued native query lost original records'
