from confluent_kafka import TopicPartition,KafkaException,ElectionType
from confluent_kafka.admin import ConfigResource,ResourceType,ConfigEntry,AlterConfigOpType,ConfigSource
import time
def recover(admin,topic,allow_loss=False):
    if type(allow_loss) is not bool:raise ValueError('explicit boolean RPO authorization required')
    if not allow_loss:
        p=admin.list_topics(topic,timeout=4).topics[topic].partitions[0]
        r=ConfigResource(ResourceType.TOPIC,topic);actual=admin.describe_configs([r])[r].result(8)['unclean.leader.election.enable'].value
        return {'available':p.leader>=0,'leader':p.leader,'unclean_enabled':actual=='true'}
    r=ConfigResource(ResourceType.TOPIC,topic,incremental_configs=[ConfigEntry('unclean.leader.election.enable','true',incremental_operation=AlterConfigOpType.SET)])
    admin.incremental_alter_configs([r])[r].result(8)
    results=admin.elect_leaders(ElectionType.UNCLEAN,[TopicPartition(topic,0)]).result(8)
    for error in results.values():
        if error is not None:
            detail=error.args[0] if isinstance(error,KafkaException) else error
            if detail.name()!='ELECTION_NOT_NEEDED':raise KafkaException(detail)
    deadline=time.monotonic()+12
    while True:
        p=admin.list_topics(topic,timeout=2).topics[topic].partitions[0]
        if p.leader>=0:return {'available':True,'leader':p.leader,'unclean_enabled':True}
        if time.monotonic()>deadline:raise RuntimeError('unclean election not confirmed')
        time.sleep(.1)

