from pathlib import Path
import re
def properties(path):
    # Java Properties whitespace/separator/continuation/escape semantics.
    logical=[];pending=''
    for raw in Path(path).read_text(encoding='iso-8859-1').splitlines():
        line=pending+(raw.lstrip(' \t\f') if pending else raw)
        backslashes=len(line)-len(line.rstrip('\\'))
        if backslashes%2:pending=line[:-1];continue
        logical.append(line);pending=''
    if pending:logical.append(pending)
    def unescape(value):
        def decode(match):
            text=match.group(0)[1:]
            if text.startswith('u') and len(text)==5:return chr(int(text[1:],16))
            return {'t':'\t','n':'\n','r':'\r','f':'\f'}.get(text,text)
        return re.sub(r'\\u[0-9a-fA-F]{4}|\\.',decode,value)
    result={}
    for raw in logical:
        line=raw.lstrip(' \t\f')
        if not line or line[0] in '#!':continue
        escaped=False;end=len(line)
        for i,ch in enumerate(line):
            if not escaped and ch in '=:\t\f ':end=i;break
            if ch=='\\':escaped=not escaped
            else:escaped=False
        rest=line[end:].lstrip(' \t\f')
        if rest.startswith(('=',':')):rest=rest[1:].lstrip(' \t\f')
        result[unescape(line[:end])]=unescape(rest)
    return result

def validate_storage(admin,config_path):
    cfg=properties(config_path);dirs=[Path(x.strip()).resolve() for x in cfg['log.dirs'].split(',')]
    cluster=admin.list_topics(timeout=4).cluster_id
    if not cluster:raise ValueError('native cluster identity unknown')
    result=[]
    for directory in dirs:
        path=directory/'meta.properties'
        if not path.is_file():raise ValueError('existing formatted directory required')
        meta=properties(path)
        if meta.get('cluster.id')!=cluster or meta.get('node.id')!=cfg.get('node.id'):raise ValueError('storage identity mismatch; preserve original files')
        result.append({'directory':str(directory),'cluster_id':meta['cluster.id'],'node_id':int(meta['node.id']),'directory_id':meta.get('directory.id')})
    return result

