from confluent_kafka import Producer

def emit(bootstrap,topic,records):
    delivered=[];errors=[]
    p=Producer({'bootstrap.servers':bootstrap,'partitioner':'murmur2','acks':'all','enable.idempotence':False})
    def ack(error,message):
        if error is not None:errors.append(error)
        else:delivered.append({'key':message.key().decode(),'value':message.value().decode(),'partition':message.partition(),'offset':message.offset()})
    for key,value in records:p.produce(topic,key=key,value=value,on_delivery=ack)
    if p.flush(10)!=0 or errors:raise RuntimeError('native ACK not confirmed')
    return delivered

def routing_change(before,after):
    old={x['key']:x['partition'] for x in before};new={x['key']:x['partition'] for x in after}
    changed=sorted(k for k in old.keys()&new.keys() if old[k]!=new[k])
    return {'changed_keys':changed,'partition_local_order_only':True,'cross_partition_handoff_required':bool(changed)}

