from collections import Counter,defaultdict
import math

def diagnose(admin,topics,messages,seconds):
    if isinstance(seconds,bool) or not isinstance(seconds,(int,float)) or not math.isfinite(seconds) or seconds<=0:raise ValueError('positive observed sampling duration required')
    metadata=admin.list_topics(timeout=4);brokers=sorted(metadata.brokers);leaders=Counter({n:0 for n in brokers})
    counts=Counter();sizes=Counter();keys=defaultdict(Counter)
    for topic in topics:
        md=metadata.topics.get(topic)
        if md is None or md.error:raise ValueError('topic metadata unknown')
        for partition in md.partitions.values():
            if partition.leader<0:raise ValueError('offline partition is not a normal hotspot sample')
            leaders[partition.leader]+=1
            counts[(topic,partition.id)]=0;sizes[(topic,partition.id)]=0
    for message in messages:
        pair=(message.topic(),message.partition())
        if pair not in counts:raise ValueError('sample outside requested topic set')
        counts[pair]+=1;sizes[pair]+=len(message.value() or b'')
        if message.key() is not None:keys[pair][message.key()]+=1
    total=sum(counts.values());mean=total/len(counts) if counts else 0
    hot=sorted(pair for pair,n in counts.items() if mean>0 and n>2*mean)
    skew=any(keys[pair] and keys[pair].most_common(1)[0][1]>=.8*counts[pair] for pair in hot)
    imbalance=bool(leaders and max(leaders.values())>math.ceil(sum(leaders.values())/len(leaders)))
    return {'key_skew':skew,'leader_imbalance':imbalance,'leaders_by_broker':dict(leaders),
        'record_rates':{topic+':'+str(part):n/seconds for (topic,part),n in counts.items()},
        'byte_rates':{topic+':'+str(part):n/seconds for (topic,part),n in sizes.items()},
        'dominant_keys':{topic+':'+str(part):counter.most_common(1)[0][0].hex() for (topic,part),counter in keys.items() if counter}}

