from confluent_kafka.admin import ConfigResource,ResourceType,ConfigEntry,AlterConfigOpType,ConfigSource

def _read(admin,kind,name):
    r=ConfigResource(kind,str(name));return admin.describe_configs([r])[r].result(8)
def _write(admin,kind,name,values):
    r=ConfigResource(kind,str(name),incremental_configs=[ConfigEntry(k,str(v) if v is not None else None,
      incremental_operation=AlterConfigOpType.DELETE if v is None else AlterConfigOpType.SET) for k,v in values.items()])
    admin.incremental_alter_configs([r])[r].result(8)
def apply(admin,topic,brokers,rate):
    if type(rate) is not int or rate<=0 or not brokers or any(type(x) is not int for x in brokers) or len(set(brokers))!=len(brokers):raise ValueError('finite positive rate and distinct brokers required')
    metadata=admin.list_topics(topic,timeout=4)
    if not set(brokers)<=set(metadata.brokers):raise ValueError('unknown broker')
    partitions=metadata.topics[topic].partitions
    pairs=','.join(str(p)+':'+str(b) for p in sorted(partitions) for b in sorted(brokers))
    specs=[('BROKER',str(b),{'leader.replication.throttled.rate':rate,'follower.replication.throttled.rate':rate}) for b in brokers]
    specs.append(('TOPIC',topic,{'leader.replication.throttled.replicas':pairs,'follower.replication.throttled.replicas':pairs}))
    token=[]
    try:
        for name,resource,values in specs:
            kind=getattr(ResourceType,name);old=_read(admin,kind,resource)
            if any(k in old and ConfigSource(old[k].source).name=='UNKNOWN_CONFIG' for k in values):raise ValueError('native config source required before mutation')
            previous={k:old[k].value if k in old and ConfigSource(old[k].source).name in ('DYNAMIC_BROKER_CONFIG','DYNAMIC_TOPIC_CONFIG') else None for k in values}
            token.append({'kind':name,'resource':resource,'previous':previous})
            _write(admin,kind,resource,values)
    except Exception:
        restore(admin,token);raise
    return token
def restore(admin,token):
    for row in reversed(token):_write(admin,getattr(ResourceType,row['kind']),row['resource'],row['previous'])

