import re,subprocess,time
from confluent_kafka import TopicCollection, KafkaException
from confluent_kafka.admin import NewTopic,ConfigResource,ResourceType

def _quota(command,owner):
    result=subprocess.run([*command,'--describe','--entity-type','clients','--entity-name',owner],capture_output=True,text=True,timeout=12)
    if result.returncode:raise RuntimeError('native client quota unavailable')
    match=re.search(r'producer_byte_rate=([0-9.]+)',result.stdout)
    return float(match.group(1)) if match else None

def _change(command,owner,value):
    args=['--alter','--entity-type','clients','--entity-name',owner]
    args+=['--delete-config','producer_byte_rate'] if value is None else ['--add-config','producer_byte_rate='+str(value)]
    result=subprocess.run([*command,*args],capture_output=True,text=True,timeout=12)
    if result.returncode:raise RuntimeError('native client quota update failed')

def _topic_identity(admin,name):
    deadline=time.monotonic()+8
    while True:
        try:return str(admin.describe_topics(TopicCollection([name]))[name].result(4).topic_id)
        except KafkaException as error:
            if error.args[0].code() not in (3,5,100) or time.monotonic()>=deadline:raise
            time.sleep(.1)

def admit(admin,command,request,policy):
    owner=request.get('owner');name=request.get('topic');oncall=request.get('oncall')
    if not all(isinstance(x,str) and x.strip() for x in [owner,name,oncall]) or not re.fullmatch(r'[a-z0-9][a-z0-9._-]{0,180}',owner) or not name.startswith(owner+'.'):raise ValueError('owner/topic namespace and monitoring owner required')
    numbers=['partitions','message_bytes','messages_per_second','retention_ms','recovery_window_ms','p99_target_ms']
    if any(type(request.get(k)) is not int or request[k]<=0 for k in numbers):raise ValueError('finite positive explicit budgets required')
    key_counts=request.get('key_counts')
    if not isinstance(key_counts,dict) or not key_counts or any(not isinstance(k,str) or not k or type(v) is not int or v<=0 for k,v in key_counts.items()):raise ValueError('observed key distribution required')
    if max(key_counts.values())/sum(key_counts.values())>policy['max_key_fraction']:raise ValueError('observed key hotspot exceeds admission policy')
    tier=policy['tiers'].get(request.get('tier'))
    if tier is None:raise ValueError('unknown reliability tier')
    rate=(request['message_bytes']+policy['record_overhead_bytes'])*request['messages_per_second']
    rf=tier['replicas'];storage=(rate*request['retention_ms']*rf+999)//1000+policy['partition_overhead_bytes']*request['partitions']*rf
    if request['partitions']>policy['max_partitions'] or request['message_bytes']>policy['max_message_bytes'] or request['retention_ms']>policy['max_retention_ms'] or request['retention_ms']<request['recovery_window_ms']*policy['retention_safety_factor'] or rate>policy['max_ingress_bytes_per_second'] or rate*rf>policy['max_replicated_bytes_per_second'] or storage>policy['max_storage_bytes']:raise ValueError('admission exceeds explicit capacity/recovery policy')
    metadata=admin.list_topics(timeout=4)
    if rf>len(metadata.brokers):raise ValueError('insufficient actual brokers for tier')
    old_quota=_quota(command,owner)
    if old_quota is not None and old_quota!=rate:raise ValueError('existing owner quota must not be overwritten')
    existed=name in metadata.topics;created=False;quota_changed=False
    expected={'retention.ms':str(request['retention_ms']),'min.insync.replicas':str(tier['min_isr']),'max.message.bytes':str(request['message_bytes']+policy['record_overhead_bytes'])}
    if existed:
        r=ConfigResource(ResourceType.TOPIC,name);current=admin.describe_configs([r])[r].result(8)
        md=metadata.topics[name]
        if len(md.partitions)!=request['partitions'] or any(len(p.replicas)!=rf for p in md.partitions.values()) or any(current[k].value!=v for k,v in expected.items()):raise ValueError('existing topic configuration differs; preserve it')
    try:
        if old_quota is None:_change(command,owner,rate);quota_changed=True
        if not existed:admin.create_topics([NewTopic(name,request['partitions'],rf,config=expected)])[name].result(8);created=True
        identity=_topic_identity(admin,name)
        return {'topic':name,'topic_id':identity,'owner':owner,'oncall':oncall,'estimated_storage_bytes':storage,'producer_rate':rate,'replicas':rf,'p99_target_ms':request['p99_target_ms'],'quota_created':quota_changed}
    except Exception:
        if created:admin.delete_topics([name])[name].result(8)
        if quota_changed:_change(command,owner,None)
        raise

def retire(admin,command,receipt):
    owner=receipt.get('owner');name=receipt.get('topic');identity=receipt.get('topic_id');rate=receipt.get('producer_rate')
    if not isinstance(owner,str) or not re.fullmatch(r'[a-z0-9][a-z0-9._-]{0,180}',owner) or not isinstance(name,str) or not name.startswith(owner+'.') or not isinstance(identity,str) or not identity or type(rate) is not int or rate<=0 or type(receipt.get('quota_created')) is not bool:raise ValueError('coherent owner/topic/UUID and explicit quota lifecycle receipt required')
    metadata=admin.list_topics(timeout=4);exists=name in metadata.topics
    if exists:
        actual=_topic_identity(admin,name)
        if actual!=identity:raise ValueError('stale receipt cannot delete a replacement topic')
    value=_quota(command,owner)
    if value is not None and value!=rate:raise ValueError('foreign changed quota must be preserved before deleting a topic')
    # A matching pre-existing quota was not created by this invocation.
    # Its presence does not authorize its removal. No ownership registry is invented.
    if exists:admin.delete_topics([name])[name].result(8)
    if receipt['quota_created'] and value is not None:_change(command,owner,None)

