import java.time.Duration;
import java.util.Properties;
import java.util.concurrent.CountDownLatch;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.common.utils.Bytes;
import org.apache.kafka.streams.*;
import org.apache.kafka.streams.kstream.*;
import org.apache.kafka.streams.processor.api.*;
import org.apache.kafka.streams.state.*;

public class WindowDriver {
  public static void main(String[] args) throws Exception {
    if(args.length!=10) throw new IllegalArgumentException("bootstrap,input,updates,finals,app,window,grace,dedup,eventtime,state-dir");
    long window=Long.parseLong(args[5]), grace=Long.parseLong(args[6]);
    boolean dedup=Boolean.parseBoolean(args[7]), eventtime=Boolean.parseBoolean(args[8]);
    StreamsBuilder builder=new StreamsBuilder();
    Consumed<String,String> consumed=Consumed.with(Serdes.String(),Serdes.String());
    if(eventtime) consumed=consumed.withTimestampExtractor((record,partitionTime)->Long.parseLong(record.value().toString().split("\\|",-1)[2]));
    KStream<String,String> input=builder.stream(args[1],consumed);
    if(dedup) {
      builder.addStateStore(Stores.windowStoreBuilder(Stores.persistentWindowStore("seen",Duration.ofMillis(2*window+grace+1),Duration.ofMillis(window),false),Serdes.String(),Serdes.String()));
      input=input.processValues(()->new FixedKeyProcessor<String,String,String>() {
        FixedKeyProcessorContext<String,String> context;
        WindowStore<String,String> seen;
        public void init(FixedKeyProcessorContext<String,String> c) { context=c; seen=c.getStateStore("seen"); }
        public void process(FixedKeyRecord<String,String> r) {
          String id=r.value().split("\\|",-1)[0];
